function Villa.HousingVendorData:IsHousingMaterial(itemID)
    itemID = tonumber(itemID)
    if not itemID then return false end
    return self.materials and self.materials[itemID] == true or false
end

function Villa.HousingVendorData:GetVendorByNpcID(npcID)
    npcID = tonumber(npcID)
    if not npcID then return nil end
    for _, vendor in ipairs(self.vendors or {}) do
        if vendor.npcID == npcID then return vendor end
    end
    return nil
end
